# Replace policies() with the requested taxonomy, custom type creation and cross-linked people view.
def replace_method(src, name, replacement):
    start = src.find('    private void ' + name + '(){')
    if start < 0: raise SystemExit('Method not found: '+name)
    brace = src.find('{', start); depth = 0
    for i in range(brace, len(src)):
        if src[i] == '{': depth += 1
        elif src[i] == '}':
            depth -= 1
            if depth == 0: return src[:start] + replacement + src[i+1:]
    raise SystemExit('Unbalanced method: '+name)

