new_save = r'''    private void saveClient(EditText holder,EditText surname,EditText name,EditText dni,EditText cif,EditText birth,EditText nationality,EditText sex,EditText address,EditText birthPlace,EditText parents,EditText support,EditText issue,EditText validity,EditText phone,EditText email,EditText number,String idType,String type,String raw,String insuredText,String productText){try{JSONArray a=data();String idNumber=idType.equals("CIF empresa")?cif.getText().toString().trim().toUpperCase(Locale.ROOT):dni.getText().toString().trim().toUpperCase(Locale.ROOT);JSONObject p=new JSONObject();String policyNumber=number.getText().toString().trim();String pid="P-"+System.currentTimeMillis();for(int i=0;i<a.length();i++){JSONObject old=a.optJSONObject(i);if(old!=null&&!policyNumber.isEmpty()&&policyNumber.equalsIgnoreCase(old.optString("number",""))){pid=old.optString("policyId",pid);break;}}p.put("policyId",pid);p.put("holder",holder.getText().toString().trim());p.put("surname",surname.getText().toString().trim());p.put("name",name.getText().toString().trim());p.put("holderDni",dni.getText().toString().trim().toUpperCase(Locale.ROOT));p.put("identityType",idType);p.put("identityNumber",idNumber);p.put("cif",cif.getText().toString().trim().toUpperCase(Locale.ROOT));p.put("birthDate",birth.getText().toString().trim());p.put("nationality",nationality.getText().toString().trim());p.put("sex",sex.getText().toString().trim());p.put("address",address.getText().toString().trim());p.put("birthPlace",birthPlace.getText().toString().trim());p.put("parents",parents.getText().toString().trim());p.put("supportNumber",support.getText().toString().trim());p.put("issueDate",issue.getText().toString().trim());p.put("validityDate",validity.getText().toString().trim());p.put("expiry",validity.getText().toString().trim());p.put("phone",phone.getText().toString().trim());p.put("email",email.getText().toString().trim());p.put("number",policyNumber);p.put("type",type.equalsIgnoreCase("Decesos")?"Deceso":type);p.put("ocrText",raw);p.put("updatedAt",System.currentTimeMillis());if("Deceso".equalsIgnoreCase(p.optString("type","")))p.put("product",productText==null?"":productText.trim());JSONArray insured=parseInsuredLines(insuredText,p.optString("holder",""));if(insured.length()==0)insured=extractInsuredsFromOcr(raw,p.optString("holder",""));p.put("insureds",insured);JSONArray docs=new JSONArray();for(int i=0;i<sessionPaths.size();i++){JSONObject doc=new JSONObject();doc.put("path",sessionPaths.get(i));doc.put("side",dniMode?(i==0?"ANVERSO":"REVERSO"):"DOCUMENTO "+(i+1));doc.put("addedAt",System.currentTimeMillis());docs.put(doc);}p.put("documentPhotos",docs);boolean replaced=false;for(int i=0;i<a.length();i++){JSONObject old=a.optJSONObject(i);if(old!=null&&pid.equals(old.optString("policyId",""))){a.put(i,p);replaced=true;break;}}if(!replaced)a.put(p);save(a);updatePeopleIndex(p);Toast.makeText(this,"Póliza guardada. Tomador y "+insured.length()+" asegurado(s) vinculados.",Toast.LENGTH_LONG).show();home();}catch(Exception e){Toast.makeText(this,"No se pudo guardar: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
'''
